def semina(apps, schema_editor):
    Categoria = apps.get_model("tasks", "TaskCategory")
    for tappa, nome, slug, descrizione in NUOVI:
        if Categoria.objects.filter(tappa=tappa).exists():
            continue
        cat = Categoria.objects.filter(slug=slug).first()
        if cat is None:
            cat = Categoria.objects.create(name=nome if not Categoria.objects.filter(name=nome).exists() else f"{nome} (kickoff)",
                                           slug=slug, description=descrizione)
        cat.tappa = tappa
        cat.save(update_fields=["tappa"])


